import ast
import os

def get_docstring(node):
    if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
        doc = ast.get_docstring(node)
        return doc.split('\n')[0].strip() if doc else ""
    return ""

def get_module_info(filepath):
    with open(filepath, "r", encoding="utf-8") as f:
        tree = ast.parse(f.read())

    results = []
    for node in tree.body:
        # Sınıflar
        if isinstance(node, ast.ClassDef):
            if not node.name.startswith('_'):
                doc = get_docstring(node)
                sig = f"class {node.name}"
                results.append(f"- `{sig}` — {doc}")
                # Sınıf metotları
                for item in node.body:
                    if isinstance(item, (ast.FunctionDef, ast.AsyncFunctionDef)):
                        if not item.name.startswith('_') and item.name != "__init__":
                            m_prefix = "async " if isinstance(item, ast.AsyncFunctionDef) else ""
                            # Unparse ile metodun imzasını alalım (self dahil)
                            try:
                                m_sig_raw = ast.unparse(item).replace("def ", "").replace("async def ", "async ")
                                if ":" in m_sig_raw:
                                    m_sig_raw = m_sig_raw.split(":")[0].strip()
                                results.append(f"- `{node.name}.{m_sig_raw}` — {get_docstring(item)}")
                            except:
                                pass

        # Fonksiyonlar (modül düzeyinde)
        elif isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            if not node.name.startswith('_'):
                doc = get_docstring(node)
                m_sig_raw = ast.unparse(node).replace("def ", "").replace("async def ", "async ")
                if ":" in m_sig_raw:
                    m_sig_raw = m_sig_raw.split(":")[0].strip()
                results.append(f"- `{m_sig_raw}` — {doc}")
    return results

def generate_api_md():
    paket_dir = "paket"
    output_file = "API.md"
    content = []

    # Dosyaları listele ve kurallara göre filtrele
    files = []
    for f in sorted(os.listdir(paket_dir)):
        if f.endswith(".py"):
            # _ ile başlayanlar hariç ( __init__.py istisnası değil, o zaten boşsa atlanacak)
            if f.startswith("_") and f != "__init__.py":
                continue

            filepath = os.path.join(paket_dir, f)
            # __init__.py boşsa atla
            if f == "__init__.py" and os.path.getsize(filepath) == 0:
                continue

            files.append(f)

    for f in files:
        module_name = f[:-3] if f.endswith(".py") else f
        # __init__ modül başlığı olarak genellikle istenmez ama kuralda özel bir durum yoksa 
        # sadece boş değilse işleme alıyoruz. Ancak genelde API dokümanlarında paket ismi verilir.
        if module_name == "__init__":
            continue

        filepath = os.path.join(paket_dir, f)
        info = get_module_info(filepath)

        if info: # Eğer modülde belgelenecek bir şey varsa başlık ekle
            content.append(f"## paket.{module_name}")
            for line in info:
                content.append(line)
            content.append("") 

    with open(output_file, "w", encoding="utf-8") as f:
        f.write("\n".join(content))

generate_api_md()

